#include <stdio.h>

int main(void) {
    double a, b, soma;
    scanf("%lf %lf", &a, &b);
    soma = a + b;
    if (soma > 20.0) {
        printf("%.2f\n", soma + 8.0);
    } else {
        printf("%.2f\n", soma - 5.0);
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    int n;
    scanf("%d", &n);
    if (n % 3 == 0 && n % 7 == 0) {
        printf("divisivel por 3 e por 7\n");
    } else {
        printf("nao e divisivel por 3 e por 7\n");
    }
    return 0;
}

#include <stdio.h>

int main(void) {
    double sb, vp;
    scanf("%lf %lf", &sb, &vp);
    if (vp <= 0.3 * sb) {
        printf("emprestimo concedido\n");
    } else {
        printf("emprestimo negado\n");
    }
    return 0;
}
